 // src/components/Questions/QuestionDetails.js

import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import './QuestionDetails.css';
import HomeIcon from '../Common/HomeIcon';
import AnswerForm from '../Answers/AnswerForm';
// Importă ambele funcții, inclusiv deleteAnswer
import { getQuestionById, getAnswersByQuestionId, deleteAnswer } from '../../services/api';

function QuestionDetails() {
  const { id } = useParams();
  const [question, setQuestion] = useState(null);
  const [answers, setAnswers] = useState([]);
  const [likes, setLikes] = useState(0); 
  const [currentUserId, setCurrentUserId] = useState(null);
 
    useEffect(() => { 
    const token = localStorage.getItem('token');
    if (token) { 
        const userId = localStorage.getItem('userId');  
        setCurrentUserId(userId ? Number(userId) : null);  
    } else {
        setCurrentUserId(null);  
    }
 
    getQuestionById(id)
      .then(data => {
        setQuestion(data);
        setLikes(data.voteScore || 0);  
      })
      .catch(err => console.error('Eroare la încărcarea întrebării:', err));

    
    getAnswersByQuestionId(id)
      .then(data => setAnswers(data))
      .catch(err => console.error('Eroare la încărcarea răspunsurilor:', err));

  }, [id]);  

 
  const handleVote = type => {
    setLikes(prev => prev + (type === 'like' ? 1 : -1));
  };
 
  const handleDeleteAnswer = async (answerId) => { 
    if (window.confirm('Sigur doriți să ștergeți acest răspuns?')) {
      try { 
        const result = await deleteAnswer(answerId, currentUserId);
        console.log("Backend response for delete:", result.message); 
 
        if (result.message === "Answer deleted successfully.") { 
            setAnswers(prevAnswers => prevAnswers.filter(answer => answer.id !== answerId));
             alert('Răspuns șters cu succes!');
        } else { 
             alert('Nu s-a putut șterge răspunsul: ' + result.message);
        }

      } catch (error) { 
        console.error('Eroare la apelul deleteAnswer API:', error);
        alert('A apărut o eroare la ștergerea răspunsului.');
      }
    }
  };

 
  if (!question) {
    return <p>Se încarcă...</p>;
  }

  return (
    <div className="question-details-container">
      <HomeIcon />

      <h2>{question.title}</h2>
      <p><strong>Autor:</strong> {question.user?.username || 'Anonim'}</p>
      <p><strong>Data:</strong> {question.date}</p>
      <p><strong>Conținut:</strong> {question.text}</p>

      <p>
        <strong>Etichete:</strong>{' '}
        {(question.questionTags || []).map(qt =>
          <span className="tag" key={qt.id}>{qt.tag.name}</span>
        )}
      </p>

      {/* Secțiunea de voturi (rămâne neschimbată, dar ar trebui conectată la backend) */}
      <div className="like-buttons">
        {/* Butoanele de vot ar trebui și ele să cheme API-ul de voturi */}
        <button onClick={() => handleVote('like')}>👍</button>
        <button onClick={() => handleVote('dislike')}>👎</button>
        <span>{likes} voturi</span>
      </div>

      <h3>Răspunsuri:</h3>

      {/* Lista de Răspunsuri */}
      {answers.length === 0 ? (
        <p><i>Încă nu există răspunsuri pentru această întrebare.</i></p>
      ) : (
        <ul>
          {answers.map(answer => (
            <li key={answer.id}>
              <p>{answer.text}</p>
              <p style={{ fontSize: '0.85em', color: '#666' }}>
                — {answer.user?.username || 'Utilizator necunoscut'}
                 
                {currentUserId !== null && answer.user && answer.user.id === currentUserId && (
                    <button
                        onClick={() => handleDeleteAnswer(answer.id)} 
                        style={{ marginLeft: '10px', fontSize: '0.8em', cursor: 'pointer', color: 'red' }} 
                    >
                        Șterge
                    </button>
                )}
              </p>
            </li>
          ))}
        </ul>
      )}

      {/* Formularul de Adăugare Răspuns - Afișat doar dacă utilizatorul este logat */}
      {currentUserId && (
           <AnswerForm
                questionId={id} 
                onAnswerSubmitted={(newAnswer) => { 
                    setAnswers(prevAnswers => [...prevAnswers, newAnswer]);
                }}
            />
      )}

    </div>
  );
}

export default QuestionDetails;
